INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('1b52c5d7-c688-477e-b2a6-2691a0ced20c', 'Fecha de Apertura', '21 de diciembre de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('1b52c5d7-c688-477e-b2a6-2691a0ced20c', 'Incremento de Renta', '12', '8', 'RENTA Y FORMA DE PAGO', E'- After one year from the Rent Payment Start Date, and annually thereafter, the monthly rent will increase based on the percentage increase of the National Consumer Price Index (INPC) from the previous 12 months.\n- The increase cannot exceed 10%.\n- If the increase is more than 16%, both parties will meet to agree on the new rent amount.', 'Transcurrido un año a partir de la Fecha de Inicio de Pago de la Renta y posteriormente de manera anual, la RENTA MENSUAL serán incrementadas anualmente en el mismo porcentaje de incremento que se haya registrado durante los últimos 12 (doce) meses inmediatos anteriores, el Índice Nacional de Precios al Consumidor (INPC) que publica el Instituto Nacional de Estadísticas y Geografía (INEGI). En la inteligencia de que dichos aumentos no podrán ser mayores al 10%. Las partes acuerdan que si dicho incremento sea superior al 16%, Las Partes se reunirán y determinarán de común acuerdo el monto de la renta.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('1b52c5d7-c688-477e-b2a6-2691a0ced20c', 'Late Fees', '13', '8', 'RENTA Y FORMA DE PAGO', E'- If the subtenant doesn''t pay the monthly rent on time, they will be charged a penalty.\n- The penalty is 5% of the unpaid rent balance.\n- This penalty applies for each month the rent is late until the full amount is paid.', 'La falta de pago puntual de la RENTA MENSUAL de que se trate, generará a cargo de LA SUBARRENDATARIA una pena convencional equivalente al 5% (cinco por ciento) sobre el saldo insoluto de la RENTA MENSUAL, por cada mes de retraso en el pago de la RENTA MENSUAL y hasta en tanto dicho saldo insoluto no sea pagada en su totalidad.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('1b52c5d7-c688-477e-b2a6-2691a0ced20c', 'Common Area Maintenance Charges', '12', '8', 'RENTA Y FORMA DE PAGO', E'- The subtenant agrees to pay the sublandlord a monthly rent of $332,000.00.\n- This amount is subject to applicable Value Added Tax (VAT).\n- The rent includes the maintenance fee for the shopping center.', 'LA SUBARRENDATARIA se obliga a pagar a EL SUBARRENDADOR por concepto de renta, la cantidad de $332,000.00 (trescientos treinta y dos mil pesos 00/100 M.N.), más el Impuesto al Valor Agregado correspondiente (en lo sucesivo la "RENTA MENSUAL"), misma que incluye la cuota de mantenimiento del Centro Comercial.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('7f8c5435-e13b-469c-88ec-4c9873b1f471', 'Glorieta, SLP', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '101 Plaza Huasteca', 'Sub 01', 'Fraccionamiento San Antonio. San Luis Potosí', 'San Luis Potosí', '78435', 'MX', '101 Plaza Huasteca, Sub 01, Fraccionamiento San Antonio. San Luis Potosí, San Luis Potosí 78435', 22.1531608089, -100.954690876, 'Retail', 'Lifestyle Center', 'Sports & Recreation', 'Franchise', NULL, 2016, 2217.99, NULL, '{"map_lease_expiration_date":"2030-01-16","map_marker_color":"#A879D2","coordinate":"point|22.1531608089|-100.9546908760|accurate","city_state":"Fraccionamiento San Antonio. San Luis Potosí, San Luis Potosí","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Ejército Nacional 769, Torre B, Piso 15, Granada, Miguel Hidalgo, Ciudad de México 11520","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2035-01-16","lease_expiration_date":"2030-01-16","lease_renewal_notice":"120 Days Prior","lease_length_in_months_remaining":39,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57829,"grid_name":"Glorieta, SLP","grid_full_address":"101 Plaza Huasteca, Sub 01, Fraccionamiento San Antonio. San Luis Potosí, San Luis Potosí 78435","map_addr_1":"101 Plaza Huasteca","map_addr_2":"Sub 01","map_city_state_zip":"Fraccionamiento San Antonio. San Luis Potosí, San Luis Potosí 78435","grid_brand":"Planet Fitness","location_created_at":"2025-09-29 19:45:54","active_lease_count_over_time":51146,"location_count_over_time":57829,"remaining_rent_liability_over_time":51146}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('7f7802cd-0b51-41a9-a729-2b73881eb502', '7f8c5435-e13b-469c-88ec-4c9873b1f471', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Glorieta, SLP Lease: Controinmuebles, S.A. de C.V. (06/14/2024 - 01/16/2030)', NULL, false, 'activo', 'Lease', NULL, '2025-01-01', '2024-08-19', '2030-01-16', '2045-01-16', false, 3, NULL, 3, NULL, NULL, '2029-09-18', 'Send Notice to Renew', 67, 'Controinmuebles, S.A. de C.V.', NULL, NULL, 'Ejército Nacional 769', 'Torre B, Piso 15', 'Granada, Miguel Hidalgo', 'Ciudad de México', '11520', 'MX', NULL, NULL, 'rsanchez@gigante.com.mx | yf2hernandez@gigante.com.mx | dp1ortiz@gigante.com.mx', 150, 'percent', NULL, NULL, 827552, E'$786,240.00 M.N. (setecientos ochenta y seis mil doscientos cuarenta pesos 00/100 moneda nacional), equivalente a 2 (dos) meses de Renta y $39,312.00 M.N. (treinta y nueve mil trecientos doce pesos 00/100 moneda nacional), Mantenimiento Mensual bajo los términos y condiciones señaladas en la cláusula Décima Octava.\n\nDicha cantidad será aplicada a los últimos 2 (dos) meses del arrendamiento y mantenimiento del primer año, contado a partir de la Fecha de Apertura del Local. Esta cantidad se entregará a la Arrendadora a la firma del presente Contrato en su domicilio o en cualquiera de las modalidades estipuladas en la Cláusula Segunda del presente instrumento.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('7f7802cd-0b51-41a9-a729-2b73881eb502', 'Domicilio del Contrato', E'Calle Plaza Huasteca, No. 101, Fracc. San Antonio, Municipio de Soledad de Graciano Sánchez, San Luis Potosí, C.P. 78435.\nLocal Sub01', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('7f7802cd-0b51-41a9-a729-2b73881eb502', 'Fecha de Firma del Contrato', '14 de junio de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('7f7802cd-0b51-41a9-a729-2b73881eb502', 'Fecha de Apertura', '31 de diciembre de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7f7802cd-0b51-41a9-a729-2b73881eb502', 'Late Fees', '13', '17', 'INTERESES MORATORIOS', E'- If rent is not paid on time, the landlord can charge late fees.\n- The late fee is an additional 10% per month on the overdue amount.\n- This fee applies for each month or part of a month the payment is late.', 'La falta del pago oportuno de la renta estipulada dentro del plazo señalado, dará derecho a la Arrendadora a cobrar intereses moratorios a razón del 10% (diez por ciento) mensual adicional de su importe por el simple retraso, por cada mes o fracción en que incurra en mora.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7f7802cd-0b51-41a9-a729-2b73881eb502', 'Incremento de Renta', '6', '5', 'AJUSTE DE LA RENTA', E'- The monthly rent will increase every 12 months.\n- The increase starts from the date the premises are delivered.\n- The rent will continue to increase on each anniversary of the lease.\n- The increase will match the percentage change in the National Consumer Price Index (INPC).\n- The INPC is published by the National Institute of Statistics and Geography in the Official Gazette.\n- The increase is based on the INPC for the 12 months prior to the rent increase date.', 'Las Partes convienen que la Renta Mensual será incrementada anualmente cada 12 (doce) meses, contado a partir de la fecha de entrega del local y asi subsecuentemente cada aniversario durante toda la vigencia del arrendamiento, en el mismo porcentaje de incremento del Indice Nacional de Precios al Consumidor (INPC) que publique el Intitulo Nacional de Estadística y Geografía en el Diario Oficial de la Federación para el periodo de 12 (doce) meses inmediato anterior a la fecha en que deba incrementarse la renta mensual,');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('7f7802cd-0b51-41a9-a729-2b73881eb502', 'Common Area Maintenance Charges', '9', '10 A)', 'GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The Tenant must pay the Landlord an administration and maintenance fee equal to 5% of the Monthly Rent plus VAT.\n- This fee is calculated based on the current rent amount at the time the payment is due.\n- The Tenant cannot request an account of how these fees are used or influence the management or maintenance decisions of the Shopping Center.\n- The Landlord is required to use these funds to maintain, repair, and replace parts of the Shopping Center to keep it in good working condition.', 'La Arrendataria se obliga a cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al 5% del importe de la Renta Mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las caracteristicas de la administración o mantenimiento del Centro Comercial, sin embargo, la Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('735e4253-44d4-41ea-a64b-2ee10194de2a', 'Las Palmas', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '802 Boulevard Boulevard De Las Naciones', '56AM', 'Acapulco', 'Guerrero', '39890', 'MX', '802 Boulevard Boulevard De Las Naciones, 56AM, Acapulco, Guerrero 39890', 16.795895, -99.810869, 'Retail', 'Lifestyle Center', 'Sports & Recreation', 'Franchise', 'Multiplaza Las Palmas', 1881.21, 1881.21, NULL, '{"map_lease_expiration_date":"2031-02-26","map_marker_color":"#A879D2","coordinate":"rooftop|16.7958950000|-99.8108690000|accurate","city_state":"Acapulco, Guerrero","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"26 Boulevard Magnocentro, 5° Piso, Huixquilucan, MX-MEX 52787","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"lease_total_rent_next_month":"376994.4800","lease_base_rent_change_months":18,"lease_total_rent_change_months":18,"next_option_expiration_date":"2036-02-26","lease_expiration_date":"2031-02-26","total_monthly_rent":"376994.4800","annual_gross_rent":"4523933.7600","daily_gross_rent":"12394.33906849","recurring_rent_annual":"4523933.7600","lease_renewal_notice":"180 Days Prior","lease_length_in_months_remaining":52,"lease_most_recent_note":"No","see_l