INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('59704843-0e19-4444-8fe1-a8e5698951bf', 'Fecha de Apertura', '27 de diciembre de 2025', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('59704843-0e19-4444-8fe1-a8e5698951bf', 'Renewal Option', '6', '3 BIS', 'PROMESA UNILATERAL DE ARRENDAMIENTO', E'- The Landlord promises to enter into three additional lease agreements for the Property, each lasting 5 years, starting after the current lease ends.\n- This obligation is mandatory only for the Landlord, not the Tenant.\n- The promise is valid as long as the current lease is active.\n- The Tenant can choose to exercise this option by notifying the Landlord in writing at least 180 days before the current lease expires.\n- Once notified, both parties must sign the new lease within 30 days.', E'El Arrendador promete unilateralmente y se obliga con el Arrendatario a celebrar otros tres contratos de arrendamiento, respecto al Inmueble, con una vigencia de 5 (cinco) años cada uno, contados a partir de la fecha en que finalice la vigencia del Contrato. Dicha vigencia será forzosa para el Arrendador únicamente, es decir, para el Arrendatario no será forzosa.\n\nLa presente promesa estará vigente durante todo el término en que el Contrato lo esté, por lo que el Arrendatario podrá ejercerla durante la vigencia del mismo, notificado por escrito su intención al Arrendatario con, por lo menos, 180 (ciento ochenta) días de anticipación al vencimiento de la vigencia del Contrato, con lo cual las Partes quedarán obligadas a celebrar el contrato de arrendamiento prometido dentro de los 30 (treinta) días siguiente a la fecha de notificación.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('59704843-0e19-4444-8fe1-a8e5698951bf', 'Late Fees', '9', '5', 'INTERESES MORATORIOS', E'- If the Tenant fails to pay the Rent or any other financial obligation under the Contract, including applicable VAT, as specified in the Contract, they must pay the Landlord a late interest if requested.\n- The late interest is calculated from the date of default until the payment of the principal and generated interest is made.\n- The interest rate is double the one-day Interbank Equilibrium Interest Rate (TIIE) published by the Bank of Mexico.\n- Interest is calculated on the outstanding balance for monthly periods, even if the delay is only for one day.', 'Para el caso que el Arrendatario no cubra la Renta y/o cualquier otra obligación pecuniaria del Contrato y su respectivo I.V.A, en caso de que el pago del mismo sea aplicable, en la forma y términos estipulados en este Contrato, éste se obliga a pagar al Arrendador, si así éste se lo requiere, un interés moratorio que habrá de ser calculado, a partir de la fecha en que incurra en mora y hasta la fecha en que efectivamente sea pagado el importe del capital y los intereses generados, a la tasa mensual que resulte de multiplicar, por 2 (dos), la Tasa de Interés Interbancaria de Equilibrio a un día hábil bancario (TIIE de Fondeo), a, según publicación hecha por el Banco de México, a través de su página de internet, en el entendido que el cómputo de este interés, se hará sobre saldo insoluto por períodos mensuales, no obstante que la morosidad corresponda a un solo día.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('59704843-0e19-4444-8fe1-a8e5698951bf', 'Incremento de Renta', '8', '4', 'RENTA', E'- The first rent increase will occur in the 25th month from the start date mentioned in the Inauguration Act.\n- Subsequent increases will happen every year on the anniversary.\n- The rent increase will be based on the inflation rate from the National Consumer Price Index (INPC) for the previous 12 months.\n- Annual rent increases are capped at a maximum of 8.5%.', 'Las Partes acuerdan que el primer incremento de Renta se realizará en el mes 25 (veinticinco) contado a partir de la fecha asentada en el Acta de Inauguración posteriormente cada aniversario, aplicándose a las Rentas Mensuales pagaderas a partir e incluyendo el mes siguiente a dicho periodo, la inflación que refleje el Índice Nacional de Precios al Consumidor (en lo sucesivo denominado como INPC) publicado por el Instituto Nacional de Estadística y Geografía para los 12 (doce) meses anteriores conocidos. En la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8.5%.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('59704843-0e19-4444-8fe1-a8e5698951bf', 'Common Area Maintenance Charges', '14', '9', 'MANTENIMIENTO DEL INMUEBLE', E'- The Tenant must pay the Landlord, or a designated person, a monthly maintenance fee.\n- This fee is 12% of the Rent, plus applicable VAT.\n- The maintenance fee is paid in advance each month, along with the Rent, on the due date.\n- The fee is used for maintenance, repairs, and other necessary expenses for the Shopping Center.\n- The Tenant does not have the right to decide on the type of maintenance performed.', 'El Arrendatario se obliga a pagar al Arrendador o a la persona física o moral que designe el Arrendador una cuota de mantenimiento mensual, equivalente al 12% (doce por ciento) de la Renta, más su correspondiente I.V.A. (la Cuota de Mantenimiento), y será pagadera, por mensualidades adelantadas, junto con la Renta del mes que corresponda, en cada Fecha de Pago. La Cuota de Mantenimiento será utilizada para el adecuado mantenimiento, adaptación, reparación y demás gastos que sean necesarios y convenientes para el uso adecuado del Centro Comercial conforme lo establece el Reglamento. El pago de la Cuota de Mantenimiento no da derecho al Arrendatario para determinar o decidir sobre el tipo de mantenimiento que se debe dar en el Centro Comercial, lo cual acepta expresamente a la celebración del Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('59704843-0e19-4444-8fe1-a8e5698951bf', 'Percentage Rent', '6', '4', 'RENTA', E'- The tenant must pay 8% of their Monthly Net Sales made at the property.\n- This amount is called the ''Variable Rent.''\n- The ''Variable Rent'' is part of the total ''Rent,'' which also includes the ''Monthly Minimum Guaranteed Rent.''', 'La cantidad que resulte de aplicar el 8% (ocho por ciento] a las Ventas Netas Mensuales (según dicho término se define más adelante) que el Arrendatario realice en el Inmueble, a la cual, en lo sucesivo se le denominará como la ''Renta Variable'' y conjuntamente con la Renta Mínima Mensual De Garantía la ''Renta''.');
